insert into passages (id, text, difficulty_level, b, active) values
('c535f473-0e85-46d4-8928-bc5325adec06', 'Artificial intelligence systems are increasingly being used to assist doctors in diagnosing diseases, particularly in fields such as radiology, where AI algorithms can analyze medical images with remarkable speed and, in some cases, greater accuracy than human specialists. These systems are trained on vast datasets of medical scans, learning to identify patterns associated with specific conditions that might be difficult for the human eye to detect consistently. Proponents argue that AI-assisted diagnosis could significantly reduce diagnostic errors and help address shortages of specialists in underserved regions. However, the technology also raises important concerns. Critics point out that AI systems can inherit biases present in their training data, potentially leading to less accurate diagnoses for underrepresented populations. There are also unresolved questions about legal liability when an AI system makes an incorrect diagnosis, and many healthcare professionals emphasize that these tools should support, rather than replace, human judgment in clinical decision-making.', 4, 1.0, true),
('976faf09-2eba-4f1a-9b5b-bfa73da15ffa', 'The concept of universal basic income, in which every citizen receives a regular, unconditional cash payment from the government regardless of employment status, has moved from a fringe economic theory to a topic of serious policy debate in recent years. Supporters argue that as automation continues to eliminate certain categories of jobs, a guaranteed income could provide a crucial safety net, allowing people to pursue education, start businesses, or care for family members without the constant threat of poverty. Several pilot programs conducted in various countries have shown promising early results, including improvements in participants'' mental health and modest increases in entrepreneurial activity. Critics, however, question whether such programs are financially sustainable at a national scale, given the enormous cost of providing payments to an entire population. Some also worry that a universal basic income could reduce the incentive to work, though most pilot studies so far have found only minor effects on employment rates among recipients.', 4, 1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('b40f991a-126e-40fb-81fb-7adaef8dcd41', 'sentence_completion', 'The negotiations reached a ___ when neither side would compromise further.', NULL, '[{"id": "c", "text": "deadlock"}, {"id": "d", "text": "beginning"}, {"id": "a", "text": "solution"}, {"id": "b", "text": "celebration"}]'::jsonb, 0, '{"strategy": "neither side would compromise = אף צד לא היה מוכן להתפשר. מה קורה למו''מ כשאין פשרה?", "correct_reason": "deadlock = מבוי סתום. חוסר פשרה מוביל למבוי סתום.", "options_analysis": ["נכון! deadlock = מבוי סתום — תוצאה טבעית של חוסר נכונות להתפשר", "beginning = התחלה — לא מתאר סוף מו''מ", "solution = פתרון — הפוך מחוסר פשרה", "celebration = חגיגה — לא רלוונטי למו''מ תקוע"]}', 1.04, 1.0, 0.25, 4, 'ai', NULL, true),
('b5aba963-5a96-43cc-87aa-d3f11568b5ea', 'sentence_completion', 'The critics praised the film for its ___ portrayal of a difficult period in history.', NULL, '[{"id": "c", "text": "inaccurate"}, {"id": "b", "text": "nuanced"}, {"id": "a", "text": "boring"}, {"id": "d", "text": "careless"}]'::jsonb, 1, '{"strategy": "praised the film = שיבחו את הסרט. איזה תיאור ראוי לשבח?", "correct_reason": "nuanced = מדויק/רב-גוני. תיאור עשיר בגוונים ראוי לשבח.", "options_analysis": ["inaccurate = לא מדויק — סותר שבח", "נכון! nuanced = רב-גוני — ראוי לשבח", "boring = משעמם — הפוך משבח", "careless = חסר זהירות — הפוך משבח"]}', 1.59, 1.0, 0.25, 4, 'ai', NULL, true),
('1075ade4-7465-416e-a221-73fdd6895696', 'sentence_completion', 'The company''s aggressive marketing campaign ___ to attract younger customers.', NULL, '[{"id": "b", "text": "forgot"}, {"id": "c", "text": "refused"}, {"id": "a", "text": "failed"}, {"id": "d", "text": "celebrated"}]'::jsonb, 2, '{"strategy": "aggressive marketing campaign = קמפיין שיווקי אגרסיבי. אם לא הצליח למשוך לקוחות, מה קרה?", "correct_reason": "failed = נכשל. קמפיין שלא משך לקוחות נכשל.", "options_analysis": ["forgot = שכח — לא רלוונטי לקמפיין", "refused = סירב — לא מתאר תוצאה של קמפיין", "נכון! failed = נכשל — מתאים לתוצאה שלילית של קמפיין", "celebrated = חגג — לא מתאים לכישלון"]}', 1.33, 1.0, 0.25, 4, 'ai', NULL, true),
('a2124a2d-92e4-4ee1-b64f-8c467cead51d', 'sentence_completion', 'The historian''s account of the war was praised for being ___ and well-researched.', NULL, '[{"id": "c", "text": "careless"}, {"id": "b", "text": "biased"}, {"id": "d", "text": "brief"}, {"id": "a", "text": "thorough"}]'::jsonb, 3, '{"strategy": "well-researched = מחקר יסודי. איזו תכונה משלימה מחקר יסודי?", "correct_reason": "thorough = יסודי/מקיף. מחקר יסודי משלים תכונה זו.", "options_analysis": ["careless = חסר זהירות — הפוך ממחקר יסודי", "biased = מוטה — סותר שבח למחקר טוב", "brief = תמציתי — פחות מתאים ל''well-researched''", "נכון! thorough = יסודי — משלים ''well-researched''"]}', 1.45, 1.0, 0.25, 4, 'ai', NULL, true),
('5e9bee33-8d95-4a05-880a-7764425efcc0', 'sentence_completion', 'The council''s decision to raise taxes was met with widespread ___.', NULL, '[{"id": "d", "text": "opposition"}, {"id": "c", "text": "indifference"}, {"id": "a", "text": "celebration"}, {"id": "b", "text": "approval"}]'::jsonb, 0, '{"strategy": "raise taxes = להעלות מיסים. איך הציבור בד''כ מגיב להעלאת מיסים?", "correct_reason": "opposition = התנגדות. העלאת מיסים בד''כ פוגשת התנגדות.", "options_analysis": ["נכון! opposition = התנגדות — תגובה נפוצה להעלאת מיסים", "indifference = אדישות — פחות סביר, מיסים בד''כ מעוררים תגובה", "celebration = חגיגה — לא סביר", "approval = אישור — פחות סביר להעלאת מיסים"]}', 1.34, 1.0, 0.25, 4, 'ai', NULL, true),
('1d37d3f5-3be1-4e1f-9a88-0e2392332ba4', 'sentence_completion', 'The startup''s rapid growth ___ investors from around the world.', NULL, '[{"id": "d", "text": "discouraged"}, {"id": "a", "text": "attracted"}, {"id": "b", "text": "confused"}, {"id": "c", "text": "ignored"}]'::jsonb, 1, '{"strategy": "rapid growth = צמיחה מהירה. מה עושה צמיחה מהירה למשקיעים?", "correct_reason": "attracted = משכה. צמיחה מהירה מושכת משקיעים.", "options_analysis": ["discouraged = הרתיעה — הפוך מהיגיון עסקי", "נכון! attracted = משכה — צמיחה מהירה מושכת משקיעים", "confused = בלבלה — לא רלוונטי", "ignored = התעלמה מ- — לא הגיוני"]}', 1.0, 1.0, 0.25, 4, 'ai', NULL, true),
('00a93369-be0d-4c2e-b8be-3c3c4571eede', 'sentence_completion', 'The judge''s ruling set a ___ for future cases involving similar disputes.', NULL, '[{"id": "d", "text": "penalty"}, {"id": "a", "text": "limit"}, {"id": "c", "text": "precedent"}, {"id": "b", "text": "celebration"}]'::jsonb, 2, '{"strategy": "future cases involving similar disputes = תיקים עתידיים דומים. מה קובעת פסיקה שמשפיעה על תיקים עתידיים?", "correct_reason": "precedent = תקדים. פסיקה כזו יוצרת תקדים משפטי.", "options_analysis": ["penalty = עונש — לא מתאר את הפסיקה עצמה", "limit = הגבלה — לא מדויק כמונח משפטי כאן", "נכון! precedent = תקדים — מתאים ל''future cases''", "celebration = חגיגה — לא רלוונטי"]}', 1.06, 1.0, 0.25, 4, 'ai', NULL, true),
('33707d21-fe1e-479b-97dd-88ee5cd544b8', 'sentence_completion', 'The report''s conclusions were based on ___ evidence rather than solid data.', NULL, '[{"id": "a", "text": "conclusive"}, {"id": "d", "text": "overwhelming"}, {"id": "c", "text": "substantial"}, {"id": "b", "text": "flimsy"}]'::jsonb, 3, '{"strategy": "rather than solid data = במקום נתונים מוצקים. איזו ראיה מנוגדת לנתונים מוצקים?", "correct_reason": "flimsy = רופפת/חלשה. ראיה חלשה מנוגדת לנתונים מוצקים.", "options_analysis": ["conclusive = חד-משמעית — סותר את הניגוד", "overwhelming = מכריעה — סותר את הניגוד", "substantial = משמעותית — סותר את הניגוד ל''solid data''", "נכון! flimsy = רופפת — הניגוד המתבקש לנתונים מוצקים"]}', 0.99, 1.0, 0.25, 4, 'ai', NULL, true),
('053873eb-16e5-4975-845b-8f89d09d05cf', 'sentence_completion', 'The teacher''s ___ feedback helped the student improve significantly.', NULL, '[{"id": "a", "text": "constructive"}, {"id": "b", "text": "careless"}, {"id": "d", "text": "vague"}, {"id": "c", "text": "harsh"}]'::jsonb, 0, '{"strategy": "helped the student improve = עזר לתלמיד להשתפר. איזה משוב עוזר להשתפר?", "correct_reason": "constructive = בונה. משוב בונה תורם לשיפור.", "options_analysis": ["נכון! constructive = בונה — עוזר לתלמיד להשתפר", "careless = חסר זהירות — הפוך ממשוב מועיל", "vague = מעורפל — פחות עוזר להשתפר", "harsh = קשה — פחות מתאים לתיאור חיובי"]}', 1.18, 1.0, 0.25, 4, 'ai', NULL, true),
('6a394c77-3ee0-45f8-bb12-e126768ef98d', 'sentence_completion', 'The city''s infrastructure was not designed to ___ such a rapid increase in population.', NULL, '[{"id": "a", "text": "celebrate"}, {"id": "b", "text": "accommodate"}, {"id": "d", "text": "prevent"}, {"id": "c", "text": "ignore"}]'::jsonb, 1, '{"strategy": "rapid increase in population = עלייה מהירה באוכלוסייה. מה תשתית צריכה לעשות עם אוכלוסייה גדלה?", "correct_reason": "accommodate = להכיל/לקלוט. תשתית טובה מכילה אוכלוסייה גדלה.", "options_analysis": ["celebrate = לחגוג — לא רלוונטי לתשתית", "נכון! accommodate = להכיל — תפקיד תשתית ביחס לאוכלוסייה", "prevent = למנוע — לא תפקיד תשתית", "ignore = להתעלם מ- — לא רלוונטי"]}', 1.18, 1.0, 0.25, 4, 'ai', NULL, true),
('42a043fb-2286-4c61-b4e9-e82d4dab13ca', 'sentence_completion', 'The senator''s remarks were widely seen as an attempt to ___ public anger over the scandal.', NULL, '[{"id": "c", "text": "celebrate"}, {"id": "a", "text": "ignore"}, {"id": "b", "text": "defuse"}, {"id": "d", "text": "increase"}]'::jsonb, 2, '{"strategy": "public anger over the scandal = כעס ציבורי על השערוריה. מה מנסה סנטור לעשות לכעס?", "correct_reason": "defuse = לפרק/להרגיע. הצהרות פוליטיות בד''כ נועדו להרגיע כעס.", "options_analysis": ["celebrate = לחגוג — לא רלוונטי", "ignore = להתעלם מ- — פחות סביר, יש התייחסות מפורשת", "נכון! defuse = להרגיע — פעולה פוליטית טבעית מול כעס ציבורי", "increase = להגביר — הפוך ממטרה פוליטית טיפוסית"]}', 1.25, 1.0, 0.25, 4, 'ai', NULL, true),
('379452c2-99af-48f5-bbef-4f75d38de1f6', 'sentence_completion', 'The company''s new policy was criticized for being ___ toward part-time employees.', NULL, '[{"id": "c", "text": "supportive"}, {"id": "b", "text": "helpful"}, {"id": "d", "text": "generous"}, {"id": "a", "text": "unfair"}]'::jsonb, 3, '{"strategy": "criticized for being = בוקר על היותה. איזו מדיניות ראויה לביקורת כלפי עובדים?", "correct_reason": "unfair = לא הוגנת. מדיניות שמבקרים אותה כלפי עובדים היא בד''כ לא הוגנת.", "options_analysis": ["supportive = תומכת — לא סביר לביקורת", "helpful = מועילה — לא סביר לביקורת", "generous = נדיבה — לא סביר לביקורת", "נכון! unfair = לא הוגנת — מתאים לביקורת כלפי עובדים"]}', 1.03, 1.0, 0.25, 4, 'ai', NULL, true),
('b01a7699-4e45-45bd-b8f2-3c48441ab602', 'restatement', 'No sooner had the meeting started than the fire alarm went off.', NULL, '[{"id": "d", "text": "The fire alarm went off almost as soon as the meeting began."}, {"id": "a", "text": "The meeting started after the fire alarm stopped."}, {"id": "b", "text": "The fire alarm went off long before the meeting started."}, {"id": "c", "text": "The fire alarm never went off during the meeting."}]'::jsonb, 0, '{"strategy": "no sooner...than = ברגע ש-. משמעות: כמעט מיד אחרי.", "correct_reason": "אותה סמיכות זמנים בדיוק.", "options_analysis": ["נכון! אותה סמיכות זמנים בדיוק: כמעט מיד אחרי תחילת הפגישה", "הופך את סדר הזמנים", "הופך את סדר הזמנים", "סותר את המקור — האזעקה כן צלצלה"]}', 1.17, 1.0, 0.25, 4, 'ai', NULL, true),
('e2220b60-5159-4214-a840-de871d5d1637', 'restatement', 'The report, though lengthy, contained little useful information.', NULL, '[{"id": "d", "text": "The report contained no information at all."}, {"id": "c", "text": "Despite its length, the report contained little useful information."}, {"id": "a", "text": "The report was long and contained a great deal of useful information."}, {"id": "b", "text": "The report was short but full of useful information."}]'::jsonb, 1, '{"strategy": "though lengthy...little useful = למרות אורך, מעט תועלת. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — היה מעט מידע, לא כלום", "נכון! אותה משמעות בדיוק: למרות האורך, מעט מידע מועיל", "סותר ''little useful information''", "הפוך — ''short'' סותר ''lengthy''"]}', 1.12, 1.0, 0.25, 4, 'ai', NULL, true),
('511693e3-5fee-4d29-862a-fbf569986d97', 'restatement', 'Had the team communicated better, the project would not have failed.', NULL, '[{"id": "d", "text": "The team communicated well, so the project succeeded."}, {"id": "b", "text": "Communication had no effect on the project''s outcome."}, {"id": "c", "text": "The project failed because the team did not communicate well."}, {"id": "a", "text": "The project succeeded despite poor communication."}]'::jsonb, 2, '{"strategy": "תנאי שלישי הפוך: לא תקשרו טוב, ולכן נכשל הפרויקט.", "correct_reason": "המשמעות ההפוכה הנכונה של התנאי השלישי.", "options_analysis": ["סותר לגמרי — במקור התקשורת הייתה גרועה", "סותר את הקשר הסיבתי המפורש במקור", "נכון! תנאי שלישי הפוך: תקשורת גרועה גרמה לכישלון", "סותר ''failed'' — הפרויקט כן נכשל"]}', 1.09, 1.0, 0.25, 4, 'ai', NULL, true),
('afda5261-4c67-49be-b0f6-6dbd0045f51c', 'restatement', 'The proposal was rejected, not because it lacked merit, but because of budget constraints.', NULL, '[{"id": "b", "text": "The proposal had no connection to the budget."}, {"id": "a", "text": "The proposal was approved despite budget constraints."}, {"id": "c", "text": "The proposal was rejected because it had no merit at all."}, {"id": "d", "text": "Budget constraints, not a lack of merit, led to the proposal''s rejection."}]'::jsonb, 3, '{"strategy": "not because X, but because Y = לא בגלל X, אלא בגלל Y.", "correct_reason": "אותה סיבה מדויקת (תקציב, לא חוסר ערך).", "options_analysis": ["סותר את כל המשפט המקורי", "סותר ''was rejected'' — ההצעה נדחתה, לא אושרה", "סותר ''not because it lacked merit''", "נכון! אותה סיבה מדויקת: תקציב, לא חוסר ערך"]}', 1.47, 1.0, 0.25, 4, 'ai', NULL, true),
('c2749a77-d818-4914-a260-404f1ba3ee2d', 'restatement', 'The more complex the system, the harder it is to maintain.', NULL, '[{"id": "d", "text": "As systems become more complex, they become harder to maintain."}, {"id": "b", "text": "Complex systems are easier to maintain than simple ones."}, {"id": "c", "text": "Simple systems are harder to maintain than complex ones."}, {"id": "a", "text": "System complexity has no effect on maintenance difficulty."}]'::jsonb, 0, '{"strategy": "the more...the harder = יחס ישר בין מורכבות לקושי תחזוקה.", "correct_reason": "אותו יחס ישר בדיוק.", "options_analysis": ["נכון! אותו יחס ישר בדיוק: מורכבות עולה, קושי עולה", "הפוך גמור — מורכבות דווקא מקשה", "הפוך תפקידים — במקור מורכבות = קושי, לא פשטות", "סותר את היחס המתואר במקור"]}', 0.97, 1.0, 0.25, 4, 'ai', NULL, true),
('cc5b189e-6f5c-4396-b035-23e0d9663b67', 'restatement', 'The evidence, while circumstantial, was compelling enough to secure a conviction.', NULL, '[{"id": "a", "text": "The conviction happened without any evidence."}, {"id": "b", "text": "Although circumstantial, the evidence was strong enough to lead to a conviction."}, {"id": "d", "text": "The evidence was so weak that no conviction was possible."}, {"id": "c", "text": "The evidence was direct, not circumstantial."}]'::jsonb, 1, '{"strategy": "while circumstantial...compelling enough = נסיבתית אך משכנעת מספיק. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — הייתה ראיה", "נכון! אותה משמעות בדיוק: נסיבתית אך מספיק חזקה להרשעה", "סותר ''compelling enough to secure a conviction''", "סותר ''circumstantial'' במפורש"]}', 1.48, 1.0, 0.25, 4, 'ai', NULL, true),
('f749d6c8-ffb6-4038-ad5a-f96669557f05', 'restatement', 'Unless significant changes are made, the company risks losing its market share.', NULL, '[{"id": "a", "text": "Significant changes will guarantee the company loses market share."}, {"id": "c", "text": "The company will lose market share only if significant changes are made."}, {"id": "b", "text": "If significant changes are not made, the company risks losing market share."}, {"id": "d", "text": "The company has already lost all of its market share."}]'::jsonb, 2, '{"strategy": "unless = אלא אם כן. תנאי הפוך.", "correct_reason": "אותו תנאי בדיוק, בניסוח ''if not''.", "options_analysis": ["הפוך — שינויים אמורים למנוע את הסיכון, לא לגרום לו", "הפוך לוגית — הסיכון הוא דווקא בהיעדר שינויים", "נכון! אותו תנאי בדיוק: בלי שינויים משמעותיים, יש סיכון", "לא נאמר במקור שזה כבר קרה"]}', 0.94, 1.0, 0.25, 4, 'ai', NULL, true),
('8e85eab7-d4d7-41f6-960c-da4c61136538', 'restatement', 'The merger, once finalized, will create the largest company in the industry.', NULL, '[{"id": "d", "text": "The merger has already failed to happen."}, {"id": "b", "text": "The merger will never be finalized."}, {"id": "a", "text": "The merger created the smallest company in the industry."}, {"id": "c", "text": "Once the merger is finalized, it will create the largest company in the industry."}]'::jsonb, 3, '{"strategy": "once finalized, will create = ברגע שיושלם, ייצור. תנאי זמן.", "correct_reason": "אותה משמעות בדיוק, ניסוח מלא.", "options_analysis": ["סותר את התנאי — המיזוג אמור להתרחש", "לא נאמר במקור שהמיזוג לא יושלם", "הפוך — ''largest'' סותר ''smallest''", "נכון! אותה משמעות בדיוק: השלמת המיזוג תיצור את החברה הגדולה ביותר"]}', 1.41, 1.0, 0.25, 4, 'ai', NULL, true),
('024725cf-2fdc-4287-ac28-2ec2f4e48963', 'restatement', 'Rarely does a debut author achieve such widespread critical acclaim.', NULL, '[{"id": "a", "text": "It is unusual for a debut author to receive such widespread critical acclaim."}, {"id": "c", "text": "Debut authors always achieve widespread critical acclaim."}, {"id": "b", "text": "Critics have criticized this debut author heavily."}, {"id": "d", "text": "This debut author received no critical acclaim at all."}]'::jsonb, 0, '{"strategy": "rarely = לעיתים נדירות. יוצא דופן.", "correct_reason": "אותה משמעות בדיוק: נדיר וחריג.", "options_analysis": ["נכון! אותה משמעות בדיוק: חריג וקורה לעיתים נדירות", "הפוך — ''always'' סותר ''rarely''", "הפוך — ''acclaim'' הוא שבח, לא ביקורת שלילית", "סותר ''critical acclaim'' — הוא כן זכה להערכה"]}', 1.05, 1.0, 0.25, 4, 'ai', NULL, true),
('1963408e-645d-4b7d-8a36-7223e3c84ab5', 'restatement', 'The findings would have been more convincing had the sample size been larger.', NULL, '[{"id": "c", "text": "The findings were convincing despite a very small sample size."}, {"id": "a", "text": "The findings were less convincing because the sample size was too small."}, {"id": "d", "text": "The sample size was large, which made the findings very convincing."}, {"id": "b", "text": "Sample size had no impact on how convincing the findings were."}]'::jsonb, 1, '{"strategy": "תנאי שלישי הפוך: מדגם קטן מדי, ולכן ממצאים פחות משכנעים.", "correct_reason": "המשמעות ההפוכה הנכונה של התנאי השלישי.", "options_analysis": ["סותר ''would have been more convincing'' — הם לא היו משכנעים מספיק", "נכון! תנאי שלישי הפוך: מדגם קטן → ממצאים פחות משכנעים", "הפוך — במקור המדגם היה קטן מדי, לא גדול", "סותר את הקשר בין גודל מדגם לשכנוע"]}', 1.16, 1.0, 0.25, 4, 'ai', NULL, true),
('a718335d-e6f8-4aa6-8245-1cb843693ff2', 'restatement', 'So convincing was her argument that even her opponents agreed.', NULL, '[{"id": "c", "text": "Her argument failed to convince anyone, including her supporters."}, {"id": "a", "text": "Her opponents disagreed with her argument completely."}, {"id": "d", "text": "Her argument was so convincing that it persuaded even her opponents."}, {"id": "b", "text": "Her argument was weak and unconvincing to everyone."}]'::jsonb, 2, '{"strategy": "so convincing...that = כה משכנע...עד ש-. תוצאה קיצונית.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''even her opponents agreed''", "סותר לגמרי — המתנגדים דווקא הסכימו", "נכון! אותה משמעות בדיוק: שכנעה אפילו את המתנגדים", "סותר ''so convincing'' במפורש"]}', 0.97, 1.0, 0.25, 4, 'ai', NULL, true),
('9b593d49-daaf-44d3-a759-aab86ec7d881', 'restatement', 'Only after reviewing all the applications did the committee announce its decision.', NULL, '[{"id": "a", "text": "The committee reviewed all applications only after announcing its decision."}, {"id": "b", "text": "The committee announced its decision before reviewing any applications."}, {"id": "c", "text": "The committee never reviewed any applications."}, {"id": "d", "text": "The committee announced its decision only after reviewing all the applications."}]'::jsonb, 3, '{"strategy": "only after...did = רק אחרי...אז. תנאי הכרחי.", "correct_reason": "אותו תנאי הכרחי בדיוק.", "options_analysis": ["הופך את סדר האירועים", "הפוך — הבדיקה קדמה להכרזה, לא אחריה", "סותר ''reviewing all the applications''", "נכון! אותו תנאי הכרחי בדיוק: הכרזה רק אחרי בדיקה מלאה"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true),
('429bd56c-8b07-4363-86d4-b856e4215142', 'reading_comprehension', 'What is the passage mainly about?', 'c535f473-0e85-46d4-8928-bc5325adec06', '[{"id": "c", "text": "The use of AI in medical diagnosis, along with its benefits and concerns"}, {"id": "a", "text": "Why human doctors are no longer necessary"}, {"id": "b", "text": "How to train an AI algorithm from scratch"}, {"id": "d", "text": "The history of radiology as a medical field"}]'::jsonb, 0, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את השימוש בבינה מלאכותית לאבחון רפואי, יתרונות וחסרונות כאחד.", "correct_reason": "כל הפסקה עוסקת בתפקיד ה-AI באבחון רפואי ובחששות הנלווים.", "options_analysis": ["נכון! שימוש ב-AI באבחון רפואי + יתרונות וחששות = הנושא הכולל", "הפוך — הפסקה מדגישה שה-AI אמור לתמוך ברופאים, לא להחליפם", "לא הוראות טכניות, אלא ניתוח יישומי", "פרט קונטקסטואלי בלבד, לא הנושא הכולל"]}', 1.11, 1.0, 0.25, 4, 'ai', NULL, true),
('753825a2-3cae-4e64-b500-357870fb703c', 'reading_comprehension', 'According to the passage, in what field are AI diagnostic systems particularly used?', 'c535f473-0e85-46d4-8928-bc5325adec06', '[{"id": "b", "text": "Veterinary medicine"}, {"id": "c", "text": "Radiology"}, {"id": "a", "text": "Physical therapy"}, {"id": "d", "text": "Dentistry"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את התחום המוזכר בפסקה.", "correct_reason": "הפסקה אומרת: ''particularly in fields such as radiology''.", "options_analysis": ["לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה", "לא נאמר בפסקה"]}', 1.19, 1.0, 0.25, 4, 'ai', NULL, true),
('4ac450d6-6fde-4544-a744-926ad8671c0d', 'reading_comprehension', 'The word "proponents" in the passage most closely means:', 'c535f473-0e85-46d4-8928-bc5325adec06', '[{"id": "a", "text": "government regulators"}, {"id": "c", "text": "medical patients"}, {"id": "d", "text": "people who support something"}, {"id": "b", "text": "people who oppose something"}]'::jsonb, 2, '{"strategy": "אוצר מילים בהקשר — ''proponents argue that AI-assisted diagnosis could...help''.", "correct_reason": "proponents = תומכים/מצדדים ברעיון.", "options_analysis": ["לא קשור למשמעות המילה", "לא קשור למשמעות המילה", "נכון! proponents = תומכים ברעיון", "הפוך גמור למשמעות המילה"]}', 1.22, 1.0, 0.25, 4, 'ai', NULL, true),
('307fdc30-16b1-4bdb-8844-b6f88f99f248', 'reading_comprehension', 'What concern do critics raise about AI diagnostic systems, according to the passage?', 'c535f473-0e85-46d4-8928-bc5325adec06', '[{"id": "a", "text": "They are illegal in most countries"}, {"id": "d", "text": "They cannot analyze medical images at all"}, {"id": "b", "text": "They are too slow to be useful"}, {"id": "c", "text": "They can inherit biases from their training data"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את החשש שמעלים מבקרים בפסקה.", "correct_reason": "הפסקה אומרת: ''AI systems can inherit biases present in their training data, potentially leading to less accurate diagnoses for underrepresented populations''.", "options_analysis": ["לא נאמר בפסקה", "סותר את הפסקה — הם כן מנתחים תמונות רפואיות", "סותר את הפסקה — האלגוריתמים דווקא מהירים מאוד", "נכון! נאמר במפורש בפסקה"]}', 1.05, 1.0, 0.25, 4, 'ai', NULL, true),
('e5290efa-8325-433e-8f63-9374a32556f1', 'reading_comprehension', 'What do many healthcare professionals emphasize, according to the passage?', 'c535f473-0e85-46d4-8928-bc5325adec06', '[{"id": "b", "text": "That AI tools should support, rather than replace, human judgment"}, {"id": "d", "text": "That AI tools should completely replace human doctors"}, {"id": "a", "text": "That AI has no role at all in healthcare"}, {"id": "c", "text": "That legal liability questions have already been fully resolved"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את העמדה שמוזכרת בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''these tools should support, rather than replace, human judgment in clinical decision-making''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "הפוך גמור למה שנאמר בפסקה", "סותר את כל הפסקה", "סותר את הפסקה — השאלות עדיין לא פתורות"]}', 1.05, 1.0, 0.25, 4, 'ai', NULL, true),
('11127780-690c-45a3-a3db-ac5c8f75d5c5', 'reading_comprehension', 'What is the passage mainly about?', '976faf09-2eba-4f1a-9b5b-bfa73da15ffa', '[{"id": "b", "text": "A history of government welfare programs"}, {"id": "a", "text": "The debate surrounding universal basic income as a policy idea"}, {"id": "d", "text": "Why automation is eliminating all jobs"}, {"id": "c", "text": "How to start a small business"}]'::jsonb, 1, '{"strategy": "שאלת רעיון מרכזי — הפסקה סוקרת את הוויכוח סביב הכנסה בסיסית אוניברסלית.", "correct_reason": "כל הפסקה עוסקת ביתרונות, בממצאי הפיילוט ובביקורת על הרעיון.", "options_analysis": ["לא הנושא, רק הקשר רחב יותר", "נכון! הוויכוח על הכנסה בסיסית אוניברסלית = הנושא הכולל", "הפוך — הפסקה לא טוענת שכל המשרות נעלמות", "לא הוראות עסקיות, רק אזכור אגבי"]}', 1.13, 1.0, 0.25, 4, 'ai', NULL, true),
('2adc1d6b-0cf5-41ab-bae4-8a59199d2edd', 'reading_comprehension', 'According to supporters, what could universal basic income allow people to do?', '976faf09-2eba-4f1a-9b5b-bfa73da15ffa', '[{"id": "a", "text": "Eliminate the need for all government programs"}, {"id": "d", "text": "Avoid paying any taxes"}, {"id": "c", "text": "Pursue education, start businesses, or care for family members"}, {"id": "b", "text": "Work exclusively in automated industries"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את הטיעון של התומכים בפסקה.", "correct_reason": "הפסקה אומרת: ''allowing people to pursue education, start businesses, or care for family members without the constant threat of poverty''.", "options_analysis": ["לא נאמר בפסקה", "לא נאמר בפסקה", "נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה"]}', 0.98, 1.0, 0.25, 4, 'ai', NULL, true),
('3c87beb0-02f9-435e-979a-dd1c447b6c39', 'reading_comprehension', 'What did pilot programs show, according to the passage?', '976faf09-2eba-4f1a-9b5b-bfa73da15ffa', '[{"id": "d", "text": "A complete collapse of national economies"}, {"id": "c", "text": "A significant decrease in mental health among participants"}, {"id": "a", "text": "No effect whatsoever on any measured outcome"}, {"id": "b", "text": "Improvements in mental health and modest increases in entrepreneurial activity"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את תוצאות תוכניות הפיילוט בפסקה.", "correct_reason": "הפסקה אומרת: ''promising early results, including improvements in participants'' mental health and modest increases in entrepreneurial activity''.", "options_analysis": ["לא נאמר בפסקה", "הפוך גמור למה שנאמר בפסקה", "סותר את הפסקה — היו תוצאות מדידות", "נכון! נאמר במפורש בפסקה"]}', 1.03, 1.0, 0.25, 4, 'ai', NULL, true),
('181d8e97-bfe8-4ce3-bf78-c708129ccf1e', 'reading_comprehension', 'What concern do critics raise about universal basic income, according to the passage?', '976faf09-2eba-4f1a-9b5b-bfa73da15ffa', '[{"id": "d", "text": "Whether such programs are financially sustainable at a national scale"}, {"id": "c", "text": "That no one has ever proposed such an idea before"}, {"id": "b", "text": "That the idea has never been tested anywhere"}, {"id": "a", "text": "That it would immediately double national debt"}]'::jsonb, 0, '{"strategy": "שאלת פרט — חפש את הביקורת בפסקה.", "correct_reason": "הפסקה אומרת: ''critics...question whether such programs are financially sustainable at a national scale''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "סותר את הפסקה — הרעיון נדון ברצינות", "סותר את הפסקה — נערכו תוכניות פיילוט", "לא נאמר בפסקה"]}', 1.06, 1.0, 0.25, 4, 'ai', NULL, true),
('3be9c8b9-df9e-43c4-9e79-7060def989b9', 'reading_comprehension', 'What have most pilot studies found regarding employment rates, according to the passage?', '976faf09-2eba-4f1a-9b5b-bfa73da15ffa', '[{"id": "d", "text": "That everyone stopped working entirely"}, {"id": "b", "text": "Only minor effects on employment rates among recipients"}, {"id": "a", "text": "A massive increase in unemployment"}, {"id": "c", "text": "That employment rates are impossible to measure"}]'::jsonb, 1, '{"strategy": "שאלת פרט — חפש את הממצא לגבי תעסוקה בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''most pilot studies so far have found only minor effects on employment rates among recipients''.", "options_analysis": ["סותר את הפסקה — רק השפעה קלה נמצאה", "נכון! נאמר במפורש בפסקה", "הפוך גמור למה שנאמר בפסקה", "לא נאמר בפסקה"]}', 1.49, 1.0, 0.25, 4, 'ai', NULL, true);